select 'bbbb0003-0000-4000-8000-000000000015', v.pos, v.title, v.kind, v.body::jsonb, v.notes, v.mins
from (values
  (1, 'Diagnostic: where are you now?', 'quiz', '{"questions":[{"prompt":"The main audience for managerial accounting reports is…","options":["outside investors and regulators","internal managers making decisions","tax authorities only","the general public"],"answer":1,"explanation":"Managerial accounting is aimed inside the firm at decision-makers — see ''Managerial vs financial accounting''."},{"prompt":"A cost that stays the same in total as activity rises or falls is called…","options":["a variable cost","a fixed cost","a mixed cost","a marginal cost"],"answer":1,"explanation":"Fixed costs (like rent) stay constant in total within the relevant range — see ''Cost concepts and behavior''."},{"prompt":"Contribution margin per unit equals…","options":["selling price minus fixed cost per unit","selling price minus variable cost per unit","selling price minus total cost","fixed cost divided by units"],"answer":1,"explanation":"Contribution margin = price per unit - variable cost per unit; it is what each unit contributes toward fixed costs and profit."},{"prompt":"If fixed costs are 40,000 dollars and contribution margin is 20 dollars per unit, the break-even point in units is…","options":["800 units","2,000 units","4,000 units","20,000 units"],"answer":1,"explanation":"break-even = fixed costs / CM per unit = 40,000 / 20 = 2,000 units."},{"prompt":"Job order costing is the best fit for…","options":["identical gallons of paint made continuously","custom homes built to individual orders","refining crude oil","bottling one flavor of soda"],"answer":1,"explanation":"Job order costing traces costs to distinct, customized jobs — see ''Job order costing''."},{"prompt":"Activity-based costing improves accuracy mainly by…","options":["ignoring overhead entirely","using multiple cost drivers instead of one plant-wide rate","expensing all costs immediately","charging every product the same amount"],"answer":1,"explanation":"ABC assigns overhead using several activity cost drivers rather than a single volume measure."},{"prompt":"A favorable cost variance means…","options":["actual cost was higher than budgeted","actual cost was lower than budgeted","the budget was wrong","no variance occurred"],"answer":1,"explanation":"Favorable means actual came in below the standard or budget for a cost — see ''Budgeting and variance analysis''."},{"prompt":"In a make-or-buy decision, a cost that will not change regardless of the choice is…","options":["relevant and should be included","irrelevant and should be ignored","always a variable cost","the deciding factor"],"answer":1,"explanation":"Only costs that differ between alternatives are relevant; unavoidable costs drop out — see ''Relevant costs for decisions''."}]}'::jsonb, null, 10),
  (2, 'Managerial vs financial accounting', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Explain who uses managerial accounting and how it differs from financial accounting in audience, rules, timing, and detail. Warm-up: from the diagnostic, who is the primary reader of a managerial report?"},{"heading":"The idea","text":"Financial accounting produces standardized statements — the income statement, balance sheet, and cash flow statement — for people outside the firm: investors, lenders, and regulators. It follows external rules (such as GAAP or IFRS), reports the whole company, and looks backward at completed periods. Managerial accounting instead serves managers inside the firm who plan, control operations, and make decisions. It follows no mandated format, drills down to a single product line or department, mixes financial and operational measures, and often looks forward with forecasts and estimates. The three broad jobs of managerial accounting are planning (setting goals and budgets), controlling (comparing actual results to plan), and decision-making (choosing among alternatives)."},{"heading":"Worked examples","text":"A bank reviewing a loan reads audited financial statements — that is financial accounting: external user, standardized, historical. A plant manager deciding whether to add a night shift builds a forecast of extra units, extra labor, and extra contribution margin — that is managerial accounting: internal user, custom format, forward-looking. Another contrast: financial accounting reports one company-wide net income of 500,000 dollars; managerial accounting might split that into a profitable product line earning 700,000 dollars and a losing line dragging it down by 200,000 dollars, so a manager can act. The reports draw on the same underlying data but answer different questions."},{"heading":"Your turn","text":"1) A regulator requires your annual audited statements — financial or managerial accounting? 2) You estimate next quarter''s production cost to decide on hiring — which one? 3) Name the three broad jobs of managerial accounting. 4) True or false: managerial reports must follow GAAP. 5) Which type may report on just one department rather than the whole firm? Answers: 1) financial. 2) managerial. 3) planning, controlling, decision-making. 4) false — managerial accounting is not bound by GAAP. 5) managerial."},{"heading":"Common mistakes & exit ticket","text":"Mistake: assuming managerial reports must obey GAAP — they are internal and flexible. Mistake: thinking the two systems use different raw data; they usually share it but slice and time it differently. Exit: (a) Who is the primary audience of managerial accounting? (b) Which orientation in time does it emphasize? Answers: internal managers; forward-looking (planning and decisions), though it also reviews the past to control."}]}'::jsonb, 'Financial accounting reports the past to outsiders under strict rules; managerial accounting informs internal decisions and is free to look forward.', 12),
  (3, 'Cost concepts and behavior: fixed, variable, mixed', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Classify costs as fixed, variable, or mixed, and split a mixed cost into its two parts with the high-low method. Warm-up: if rent is 5,000 dollars a month whether you make 100 or 1,000 units, is rent fixed or variable?"},{"heading":"The idea","text":"Cost behavior describes how a cost reacts to changes in activity within the relevant range — the normal band of volume. A variable cost changes in total in proportion to activity but stays constant per unit; direct materials are the classic case. A fixed cost stays constant in total regardless of activity but shrinks per unit as volume rises; rent and salaries are typical. A mixed cost has both a fixed piece and a variable piece — a phone plan with a flat fee plus a per-minute charge. The high-low method separates a mixed cost by using the highest and lowest activity points: variable cost per unit = (cost at high - cost at low) / (units at high - units at low), and the fixed portion is whatever is left after removing the variable part at either point. The total cost line is then total cost = fixed cost + variable cost per unit times units."},{"heading":"Worked examples","text":"Direct materials run 6 dollars per unit: at 1,000 units total is 6,000 dollars, at 2,000 units total is 12,000 dollars — constant 6 dollars per unit, rising total, so variable. Factory rent is 5,000 dollars per month at any volume — constant total, so fixed; spread over 1,000 units it is 5 dollars per unit, over 2,000 units only 2.50 dollars per unit. Now a mixed cost: utilities were 3,400 dollars at 900 machine-hours (low) and 4,600 dollars at 1,500 machine-hours (high). High-low variable rate = (4,600 - 3,400) / (1,500 - 900) = 1,200 / 600 = 2 dollars per machine-hour. Fixed portion at the high point = 4,600 - (2 times 1,500) = 4,600 - 3,000 = 1,600 dollars. So total utilities cost = 1,600 + 2 times machine-hours; at 1,200 hours that predicts 1,600 + 2,400 = 4,000 dollars."},{"heading":"Your turn","text":"1) Sales commissions of 3 dollars per unit sold are fixed, variable, or mixed? 2) A manager''s 60,000 dollar salary regardless of output is which? 3) A cost equals 2,000 dollars plus 4 dollars per unit — which type? 4) Using high-low with cost 8,000 dollars at 2,000 units and 5,000 dollars at 500 units, find the variable rate per unit. 5) With that rate, find the fixed cost. Answers: 1) variable. 2) fixed. 3) mixed. 4) (8,000 - 5,000) / (2,000 - 500) = 3,000 / 1,500 = 2 dollars per unit. 5) at the low point, 5,000 - (2 times 500) = 5,000 - 1,000 = 4,000 dollars fixed."},{"heading":"Common mistakes & exit ticket","text":"Mistake: calling a cost variable because its per-unit amount looks steady — fixed costs are the steady-in-total ones, and their per-unit figure actually falls as volume rises. Mistake: applying cost behavior far outside the relevant range, where fixed costs can jump. Exit: (a) A variable cost is constant in what — total or per unit? (b) In high-low, which two activity levels do you use? Answers: constant per unit (it varies in total); the highest and lowest activity levels."}]}'::jsonb, 'Watch whether a cost is described per unit or in total: a variable cost is constant per unit but rises in total, while a fixed cost is constant in total but falls per unit as volume grows.', 14),
  (4, 'Cost-volume-profit analysis and break-even', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Compute contribution margin, find the break-even point in units and dollars, and solve for the volume needed to hit a target profit. Warm-up: if each unit sells for 25 dollars and costs 15 dollars in variable cost, how much does one unit contribute toward fixed costs?"},{"heading":"The idea","text":"Cost-volume-profit (CVP) analysis links selling price, costs, volume, and profit. Contribution margin per unit = selling price per unit - variable cost per unit; it is the amount each unit contributes to covering fixed costs and then profit. The contribution margin ratio = contribution margin per unit / selling price, the fraction of each sales dollar available for fixed costs and profit. Break-even is the volume at which profit is zero: break-even in units = fixed costs / CM per unit, and break-even in dollars = fixed costs / CM ratio. To reach a target profit, treat the target like extra fixed cost: units for target profit = (fixed costs + target profit) / CM per unit. The margin of safety is how far current sales sit above break-even."},{"heading":"Worked examples","text":"A product sells for 25 dollars with 15 dollars variable cost, so CM per unit = 25 - 15 = 10 dollars and CM ratio = 10 / 25 = 0.40. With fixed costs of 40,000 dollars: break-even in units = 40,000 / 10 = 4,000 units; break-even in dollars = 40,000 / 0.40 = 100,000 dollars (and indeed 4,000 units times 25 dollars = 100,000 dollars). To earn a target profit of 20,000 dollars: units = (40,000 + 20,000) / 10 = 60,000 / 10 = 6,000 units. Check: 6,000 units give contribution of 6,000 times 10 = 60,000 dollars, minus 40,000 fixed = 20,000 profit. If the firm currently sells 7,000 units, its margin of safety is 7,000 - 4,000 = 3,000 units, or 75,000 dollars of sales above break-even."},{"heading":"Your turn","text":"A lamp sells for 50 dollars with variable cost 30 dollars and fixed costs of 60,000 dollars. 1) Find CM per unit. 2) Find the CM ratio. 3) Find break-even in units. 4) Find break-even in dollars. 5) How many units are needed for a 30,000 dollar profit? Answers: 1) 50 - 30 = 20 dollars. 2) 20 / 50 = 0.40. 3) 60,000 / 20 = 3,000 units. 4) 60,000 / 0.40 = 150,000 dollars. 5) (60,000 + 30,000) / 20 = 90,000 / 20 = 4,500 units."},{"heading":"Common mistakes & exit ticket","text":"Mistake: dividing fixed costs by the selling price instead of by contribution margin — that ignores variable costs. Mistake: mixing the two formulas, using CM per unit when you want break-even in dollars (which needs the CM ratio). Exit: (a) Write the formula for break-even in units. (b) A product with a 10 dollar CM and a 25 dollar price has what CM ratio? Answers: break-even = fixed costs / CM per unit; 10 / 25 = 0.40."}]}'::jsonb, 'Break-even in units divides fixed costs by contribution margin per unit; break-even in dollars divides fixed costs by the contribution margin ratio. Keep straight which denominator you need.', 15),
  (5, 'Checkpoint 1', 'quiz', '{"questions":[{"prompt":"Which statement about managerial accounting is correct?","options":["It is prepared for external investors under GAAP","It serves internal managers and needs no mandated format","It only reports historical whole-company results","It replaces the audited financial statements"],"answer":1,"explanation":"Managerial accounting is internal, flexible, and often forward-looking."},{"prompt":"A cost that is constant in total but decreases per unit as volume rises is…","options":["variable","fixed","mixed","marginal"],"answer":1,"explanation":"Fixed costs stay constant in total, so the per-unit amount falls as units increase."},{"prompt":"Using high-low with utilities of 4,600 dollars at 1,500 hours and 3,400 dollars at 900 hours, the variable rate per hour is…","options":["1 dollar","2 dollars","3 dollars","4 dollars"],"answer":1,"explanation":"(4,600 - 3,400) / (1,500 - 900) = 1,200 / 600 = 2 dollars per hour."},{"prompt":"A product sells for 25 dollars with 15 dollars variable cost. Its contribution margin per unit is…","options":["10 dollars","15 dollars","25 dollars","40 dollars"],"answer":0,"explanation":"CM per unit = 25 - 15 = 10 dollars."},{"prompt":"With fixed costs of 40,000 dollars and a 10 dollar contribution margin per unit, break-even in units is…","options":["400","4,000","40,000","100,000"],"answer":1,"explanation":"break-even = fixed costs / CM per unit = 40,000 / 10 = 4,000 units."},{"prompt":"If the contribution margin ratio is 0.40 and fixed costs are 40,000 dollars, break-even in sales dollars is…","options":["16,000 dollars","40,000 dollars","100,000 dollars","160,000 dollars"],"answer":2,"explanation":"break-even in dollars = fixed costs / CM ratio = 40,000 / 0.40 = 100,000 dollars."}]}'::jsonb, null, 8),
  (6, 'Job order costing', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Accumulate the cost of a custom job from direct materials, direct labor, and applied overhead, and compute its total and per-unit cost. Warm-up: would a print shop making one custom banner use job order costing or continuous-process costing?"},{"heading":"The idea","text":"Job order costing is used when a firm makes distinct, identifiable jobs — custom homes, a batch of printed shirts, an audit engagement. Each job gets a job cost sheet that gathers three things: direct materials traced from materials requisitions, direct labor traced from time tickets, and manufacturing overhead applied using a predetermined overhead rate. That rate is set before the period as estimated overhead / estimated activity in the allocation base (often direct labor hours or machine hours). Applied overhead = predetermined rate times the actual base used by the job. Total job cost = direct materials + direct labor + applied overhead, and dividing by the number of units gives cost per unit. If applied overhead ends the period above actual overhead it is overapplied; below actual, it is underapplied."},{"heading":"Worked examples","text":"Estimated overhead for the year is 300,000 dollars and estimated direct labor hours are 20,000, so the predetermined rate = 300,000 / 20,000 = 15 dollars per direct labor hour. Job 42 uses 4,000 dollars of direct materials, 6,000 dollars of direct labor, and 200 direct labor hours. Applied overhead = 15 times 200 = 3,000 dollars. Total job cost = 4,000 + 6,000 + 3,000 = 13,000 dollars. If Job 42 produced 500 units, cost per unit = 13,000 / 500 = 26 dollars. Suppose over the whole year applied overhead totaled 305,000 dollars while actual overhead was 300,000 dollars — overhead is overapplied by 5,000 dollars, meaning jobs were charged slightly more than the real overhead incurred."},{"heading":"Your turn","text":"Estimated overhead is 200,000 dollars over 10,000 machine hours. 1) Find the predetermined overhead rate per machine hour. Job 7 uses 3,000 dollars materials, 5,000 dollars labor, and 400 machine hours. 2) Find applied overhead. 3) Find total job cost. 4) If Job 7 made 200 units, find cost per unit. 5) If actual overhead for the year was 210,000 dollars and applied was 205,000 dollars, is overhead over- or underapplied, and by how much? Answers: 1) 200,000 / 10,000 = 20 dollars per machine hour. 2) 20 times 400 = 8,000 dollars. 3) 3,000 + 5,000 + 8,000 = 16,000 dollars. 4) 16,000 / 200 = 80 dollars per unit. 5) underapplied by 210,000 - 205,000 = 5,000 dollars."},{"heading":"Common mistakes & exit ticket","text":"Mistake: using actual overhead on the job sheet — overhead is applied with the predetermined rate because actual totals are unknown until the period ends. Mistake: confusing over- and underapplied; applied above actual is overapplied. Exit: (a) What three cost elements build a job cost sheet? (b) How is the predetermined overhead rate computed? Answers: direct materials, direct labor, applied overhead; estimated overhead / estimated activity in the allocation base."}]}'::jsonb, 'In job order costing, overhead is applied — not traced — using a predetermined rate set before the period begins, because actual overhead is not known until later.', 14),
  (7, 'Process costing', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Explain when process costing fits, compute equivalent units, and find a cost per equivalent unit. Warm-up: would a soda bottler running one flavor continuously use job order or process costing?"},{"heading":"The idea","text":"Process costing suits continuous, mass production of identical units — soda, paint, gasoline, cement — where tracing cost to one unit is meaningless because units are interchangeable. Instead, costs are accumulated by process or department for a period and then averaged over the output of that period. Because some units are only partly finished at period end, we express work in equivalent units: equivalent units = fully completed units + (units in ending work in process times their percent complete). The cost per equivalent unit = total cost to account for / equivalent units. Materials and conversion (labor plus overhead) are often at different completion percentages, so they can be computed separately, but the core averaging idea is the same."},{"heading":"Worked examples","text":"A mixing department completes 8,000 units and has 4,000 units in ending inventory that are 50 percent complete. Equivalent units = 8,000 + (4,000 times 0.50) = 8,000 + 2,000 = 10,000 equivalent units. Total cost to account for is 60,000 dollars, so cost per equivalent unit = 60,000 / 10,000 = 6 dollars. The 8,000 completed units carry 8,000 times 6 = 48,000 dollars; the ending work in process carries 2,000 equivalent units times 6 = 12,000 dollars, and 48,000 + 12,000 = 60,000 dollars, which ties back to the total. Contrast with job costing: here no single unit has its own cost sheet — every finished unit simply carries the 6 dollar average."},{"heading":"Your turn","text":"A department completes 5,000 units and has 2,000 units in ending inventory that are 25 percent complete. Total cost to account for is 33,000 dollars. 1) Find the equivalent units. 2) Find the cost per equivalent unit. 3) Find the cost assigned to completed units. 4) Find the cost assigned to ending work in process. 5) Do the two amounts add back to the total? Answers: 1) 5,000 + (2,000 times 0.25) = 5,000 + 500 = 5,500 equivalent units. 2) 33,000 / 5,500 = 6 dollars. 3) 5,000 times 6 = 30,000 dollars. 4) 500 times 6 = 3,000 dollars. 5) yes, 30,000 + 3,000 = 33,000 dollars."},{"heading":"Common mistakes & exit ticket","text":"Mistake: counting partly finished units as whole units, which understates the cost per unit. Mistake: reaching for process costing on custom jobs, where job order costing belongs. Exit: (a) What does one equivalent unit represent? (b) 4,000 units that are 50 percent complete equal how many equivalent units? Answers: one full unit''s worth of work; 4,000 times 0.50 = 2,000 equivalent units."}]}'::jsonb, 'Equivalent units convert partly finished goods into a whole-unit count: 400 units that are 50 percent complete equal 200 equivalent units of work.', 14),
  (8, 'Activity-based costing', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Explain why a single plant-wide overhead rate can distort product costs, and assign overhead using activity cost pools and drivers. Warm-up: if a low-volume product needs many machine setups, will one volume-based rate over- or undercost it?"},{"heading":"The idea","text":"Traditional costing often applies all overhead with one plant-wide rate tied to a single volume measure like direct labor hours. That works poorly when products consume overhead very differently — a low-volume, complex product may demand many setups and inspections yet absorb little overhead under a volume rate. Activity-based costing (ABC) fixes this by (1) grouping overhead into activity cost pools such as setups, inspections, and machine maintenance, (2) choosing a cost driver for each pool (number of setups, number of inspections, machine hours), (3) computing an activity rate = pool cost / total driver quantity, and (4) applying overhead to each product as activity rate times the product''s use of that driver. ABC usually shifts cost onto low-volume, complex products and off of high-volume, simple ones, giving managers a truer picture."},{"heading":"Worked examples","text":"Overhead splits into two pools: setups with 100,000 dollars and 500 total setups, and inspections with 60,000 dollars and 3,000 total inspections. Activity rates: setups = 100,000 / 500 = 200 dollars per setup; inspections = 60,000 / 3,000 = 20 dollars per inspection. Product X uses 50 setups and 400 inspections: overhead = 200 times 50 + 20 times 400 = 10,000 + 8,000 = 18,000 dollars. If Product X made 2,000 units, ABC overhead per unit = 18,000 / 2,000 = 9 dollars. Under a single plant-wide rate driven only by volume, a low-volume product like X would likely have been charged far less than 18,000 dollars, hiding its true demand on setups and inspections."},{"heading":"Your turn","text":"Two pools: ordering with 80,000 dollars over 2,000 orders, and machining with 150,000 dollars over 30,000 machine hours. 1) Find the activity rate for ordering. 2) Find the activity rate for machining. Product Y uses 300 orders and 5,000 machine hours. 3) Find Y''s ordering overhead. 4) Find Y''s machining overhead. 5) Find Y''s total assigned overhead. Answers: 1) 80,000 / 2,000 = 40 dollars per order. 2) 150,000 / 30,000 = 5 dollars per machine hour. 3) 40 times 300 = 12,000 dollars. 4) 5 times 5,000 = 25,000 dollars. 5) 12,000 + 25,000 = 37,000 dollars."},{"heading":"Common mistakes & exit ticket","text":"Mistake: choosing a driver unrelated to what actually causes the cost — setup cost is driven by setups, not by units. Mistake: assuming ABC always lowers a product''s cost; it typically raises the cost of complex, low-volume products. Exit: (a) What is a cost driver? (b) How is an activity rate computed? Answers: the activity that causes a cost pool to grow; activity rate = pool cost / total quantity of the driver."}]}'::jsonb, 'A cost driver is the activity that causes a cost — number of setups, inspections, or orders — not just the volume of units produced.', 15),
  (9, 'Checkpoint 2', 'quiz', '{"questions":[{"prompt":"A firm building custom yachts to individual orders should use…","options":["process costing","job order costing","no costing system","only variable costing"],"answer":1,"explanation":"Distinct, customized jobs call for job order costing with a job cost sheet."},{"prompt":"With estimated overhead of 300,000 dollars and 20,000 estimated direct labor hours, the predetermined overhead rate is…","options":["6.67 dollars per hour","15 dollars per hour","20 dollars per hour","150 dollars per hour"],"answer":1,"explanation":"300,000 / 20,000 = 15 dollars per direct labor hour."},{"prompt":"A department completes 8,000 units and has 4,000 units 50 percent complete. Equivalent units equal…","options":["8,000","10,000","12,000","6,000"],"answer":1,"explanation":"8,000 + (4,000 times 0.50) = 8,000 + 2,000 = 10,000 equivalent units."},{"prompt":"If total cost to account for is 60,000 dollars over 10,000 equivalent units, cost per equivalent unit is…","options":["3 dollars","6 dollars","10 dollars","60 dollars"],"answer":1,"explanation":"60,000 / 10,000 = 6 dollars per equivalent unit."},{"prompt":"Activity-based costing assigns overhead using…","options":["a single plant-wide volume rate","multiple activity cost pools and drivers","direct materials only","the selling price of each product"],"answer":1,"explanation":"ABC uses several activity pools, each with its own cost driver."},{"prompt":"A setup cost pool of 100,000 dollars over 500 setups gives an activity rate of…","options":["50 dollars per setup","200 dollars per setup","500 dollars per setup","2,000 dollars per setup"],"answer":1,"explanation":"100,000 / 500 = 200 dollars per setup."}]}'::jsonb, null, 8),
  (10, 'Budgeting and variance analysis', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Describe how budgets support planning and control, and compute simple materials and labor variances split into price and quantity effects. Warm-up: if you budgeted 3 dollars per pound of material but paid 3.20 dollars, is that price difference favorable or unfavorable?"},{"heading":"The idea","text":"A budget is a formal financial plan for a future period; the master budget links sales, production, materials, labor, overhead, and cash into one coordinated plan. Control comes from comparing actual results to standards and analyzing the variances. A cost variance splits into two parts. The price (or rate) variance = (actual price - standard price) times actual quantity, capturing how much of the difference came from paying more or less per unit of input. The quantity (or efficiency) variance = (actual quantity - standard quantity allowed) times standard price, capturing how much came from using more or fewer inputs than the output should require. Labor works the same way with a rate variance and an efficiency variance. A cost variance is favorable when actual cost is below standard and unfavorable when above."},{"heading":"Worked examples","text":"Standard for materials is 2 pounds per unit at 3 dollars per pound. The firm makes 1,000 units, so the standard quantity allowed = 2 times 1,000 = 2,000 pounds. It actually uses 2,100 pounds and pays 3.20 dollars per pound. Price variance = (3.20 - 3.00) times 2,100 = 0.20 times 2,100 = 420 dollars unfavorable (paid more per pound). Quantity variance = (2,100 - 2,000) times 3.00 = 100 times 3 = 300 dollars unfavorable (used extra pounds). Total materials variance = 420 + 300 = 720 dollars unfavorable. Labor example: standard 0.5 hour per unit at 20 dollars per hour, so standard hours for 1,000 units = 500. Actual is 520 hours at 19 dollars. Rate variance = (19 - 20) times 520 = -520, that is 520 dollars favorable; efficiency variance = (520 - 500) times 20 = 400 dollars unfavorable; net labor variance = 400 - 520 = 120 dollars favorable."},{"heading":"Your turn","text":"Standard materials: 3 pounds per unit at 5 dollars per pound; the firm makes 400 units, uses 1,300 pounds, and pays 4.80 dollars per pound. 1) Find the standard quantity allowed. 2) Find the price variance and label it favorable or unfavorable. 3) Find the quantity variance and label it. 4) Find the total materials variance. 5) If actual price had instead equaled the 5 dollar standard, what would the price variance be? Answers: 1) 3 times 400 = 1,200 pounds. 2) (4.80 - 5.00) times 1,300 = -0.20 times 1,300 = 260 dollars favorable. 3) (1,300 - 1,200) times 5 = 100 times 5 = 500 dollars unfavorable. 4) 500 unfavorable - 260 favorable = 240 dollars unfavorable. 5) zero."},{"heading":"Common mistakes & exit ticket","text":"Mistake: multiplying the quantity variance by the actual price instead of the standard price — the efficiency variance uses standard price so it isolates the quantity effect. Mistake: treating every favorable variance as good; buying cheap, low-grade material can create a favorable price variance and an unfavorable quantity variance from waste. Exit: (a) Which price applies in the quantity variance? (b) For a cost, is actual above standard favorable or unfavorable? Answers: the standard price; unfavorable."}]}'::jsonb, 'For a cost, actual below standard is favorable and actual above standard is unfavorable — but favorable is not automatically good if it came from cutting quality or output.', 15),
  (11, 'Relevant costs for decisions: make-or-buy and special orders', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Identify which costs are relevant to a decision and apply that thinking to make-or-buy and special-order choices. Warm-up: money already spent on equipment you cannot recover — does it belong in a decision about the future?"},{"heading":"The idea","text":"In short-run decisions, only relevant costs matter: costs that differ between the alternatives and occur in the future. Sunk costs (already incurred) and costs that stay the same regardless of the choice are irrelevant and should be ignored. Also weigh opportunity cost — the value of the best option given up. In a make-or-buy decision, compare the avoidable cost of making (the costs that would disappear if you stopped making) against the purchase price of buying; unavoidable fixed costs that continue either way drop out. In a special-order decision at a price below normal, accept if the extra revenue exceeds the extra (usually variable) cost of filling it, provided there is idle capacity and it will not spoil regular pricing. Existing fixed costs are typically irrelevant to a one-time order because they are already being covered by regular sales."},{"heading":"Worked examples","text":"Make-or-buy: a part costs 10 dollars to make — 4 dollars materials, 3 dollars labor, 2 dollars variable overhead, and 1 dollar allocated fixed overhead that will continue no matter what. A supplier offers the part at 9.50 dollars. The relevant cost to make is only the avoidable 4 + 3 + 2 = 9 dollars; the 1 dollar allocated fixed cost is irrelevant. Since making costs 9 dollars versus buying at 9.50 dollars, keep making — buying would raise cost by 0.50 dollars per unit. Special order: normal price is 25 dollars with 15 dollars variable cost, and there is idle capacity. A customer offers 18 dollars per unit for 1,000 extra units. Relevant analysis: extra revenue 18 dollars minus extra variable cost 15 dollars = 3 dollars contribution per unit, or 3,000 dollars total. Because fixed costs do not change, accepting adds 3,000 dollars of profit even though 18 dollars is below the normal 25 dollar price."},{"heading":"Your turn","text":"A component costs 12 dollars to make: 5 dollars materials, 4 dollars labor, 2 dollars variable overhead, and 1 dollar allocated fixed overhead that continues regardless. A vendor offers it at 12.50 dollars. 1) What is the relevant (avoidable) cost to make? 2) Make or buy? Now a special order: normal price 40 dollars, variable cost 22 dollars, idle capacity, offer of 30 dollars for 500 units. 3) What is the contribution per unit on the order? 4) What is the total effect on profit? 5) Should the firm accept it? Answers: 1) 5 + 4 + 2 = 11 dollars (the 1 dollar fixed is irrelevant). 2) make — 11 dollars is below the 12.50 dollar purchase price. 3) 30 - 22 = 8 dollars. 4) 8 times 500 = 4,000 dollars more profit. 5) yes, accept, since capacity is idle and it adds 4,000 dollars."},{"heading":"Common mistakes & exit ticket","text":"Mistake: including allocated fixed costs that continue either way — they are not avoidable, so they are irrelevant. Mistake: rejecting a special order just because its price is below full cost; if there is idle capacity, any price above variable cost adds profit. Exit: (a) Name two features a cost must have to be relevant. (b) Is a sunk cost relevant? Answers: it must differ between alternatives and be in the future; no, a sunk cost is never relevant."}]}'::jsonb, 'A relevant cost differs between alternatives and lies in the future; sunk costs (already spent) and unavoidable costs are irrelevant no matter how large they look.', 15),
  (12, 'Performance measurement: responsibility centers', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Distinguish cost, profit, and investment centers and evaluate an investment center with return on investment (ROI) and residual income. Warm-up: a plant manager controls costs but not selling prices — which type of responsibility center best fits?"},{"heading":"The idea","text":"Decentralized firms divide into responsibility centers, and managers are judged only on what they control. A cost center (a maintenance department) is responsible for costs alone. A profit center (a store) controls both revenues and costs, so it is judged on profit. An investment center (a whole division) also controls the assets invested, so it is judged on profit relative to those assets. Two common measures: return on investment, ROI = operating income / average operating assets, expressed as a percent; and residual income = operating income - (required rate of return times average operating assets), a dollar amount left after covering a minimum return on the assets used. ROI encourages efficient use of assets but can discourage a good project that would lower a high divisional ROI; residual income avoids that by rewarding any project earning above the required rate."},{"heading":"Worked examples","text":"A division earns operating income of 200,000 dollars on average operating assets of 1,000,000 dollars. ROI = 200,000 / 1,000,000 = 0.20, or 20 percent. If the firm''s required rate of return is 12 percent, residual income = 200,000 - (0.12 times 1,000,000) = 200,000 - 120,000 = 80,000 dollars. Now suppose a new project would earn 90,000 dollars on 600,000 dollars of assets — a 15 percent return. Judged by ROI alone, the manager might reject it because 15 percent drags down the current 20 percent. But by residual income the project adds 90,000 - (0.12 times 600,000) = 90,000 - 72,000 = 18,000 dollars, so it is worth taking since it beats the 12 percent required rate."},{"heading":"Your turn","text":"A division has operating income of 150,000 dollars, average operating assets of 750,000 dollars, and a required rate of return of 10 percent. 1) Find its ROI. 2) Find its residual income. 3) Which center type is judged on profit relative to assets? A store controls prices and costs but not its building investment. 4) Which center type is that? 5) A maintenance department controls only its spending — which center type? Answers: 1) 150,000 / 750,000 = 0.20, or 20 percent. 2) 150,000 - (0.10 times 750,000) = 150,000 - 75,000 = 75,000 dollars. 3) investment center. 4) profit center. 5) cost center."},{"heading":"Common mistakes & exit ticket","text":"Mistake: judging a manager on results they do not control, such as blaming a cost-center manager for low sales. Mistake: relying on ROI alone, which can push managers to reject good projects that lower a high average; residual income guards against this. Exit: (a) Write the ROI formula. (b) What does residual income subtract from operating income? Answers: ROI = operating income / average operating assets; the required rate of return times average operating assets."}]}'::jsonb, 'Hold a manager accountable only for what they control: cost centers for costs, profit centers for revenues and costs, investment centers for profit relative to the assets invested.', 14),
  (13, 'Checkpoint 3', 'quiz', '{"questions":[{"prompt":"Standard price is 3 dollars per pound and actual price is 3.20 dollars for 2,100 pounds used. The materials price variance is…","options":["300 dollars favorable","420 dollars unfavorable","420 dollars favorable","720 dollars unfavorable"],"answer":1,"explanation":"(3.20 - 3.00) times 2,100 = 0.20 times 2,100 = 420 dollars unfavorable."},{"prompt":"The quantity (efficiency) variance is computed using which price?","options":["the actual price","the standard price","the market price","the selling price"],"answer":1,"explanation":"The quantity variance uses the standard price so it isolates the input-usage effect."},{"prompt":"A part costs 4 dollars materials, 3 dollars labor, 2 dollars variable overhead, and 1 dollar allocated fixed overhead that continues either way. The relevant cost to make is…","options":["10 dollars","9 dollars","1 dollar","6 dollars"],"answer":1,"explanation":"Only avoidable costs count: 4 + 3 + 2 = 9 dollars; the 1 dollar unavoidable fixed cost is irrelevant."},{"prompt":"With idle capacity, a special order should be accepted if its price exceeds…","options":["full cost per unit","the normal selling price","the variable cost per unit","total fixed costs"],"answer":2,"explanation":"With spare capacity, any price above variable cost adds contribution and profit."},{"prompt":"A division earns 200,000 dollars operating income on 1,000,000 dollars of average operating assets. Its ROI is…","options":["10 percent","20 percent","50 percent","200 percent"],"answer":1,"explanation":"ROI = 200,000 / 1,000,000 = 0.20, or 20 percent."},{"prompt":"With operating income of 200,000 dollars, assets of 1,000,000 dollars, and a required return of 12 percent, residual income is…","options":["24,000 dollars","80,000 dollars","120,000 dollars","200,000 dollars"],"answer":1,"explanation":"200,000 - (0.12 times 1,000,000) = 200,000 - 120,000 = 80,000 dollars."}]}'::jsonb, null, 8),
  (14, 'Capstone: a costing and decision case', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Combine cost behavior, CVP, overhead application, and relevant-cost analysis to work a single business case end to end. Warm-up: before deciding on a special order, which costs from the case will you ignore, and why?"},{"heading":"The setup","text":"Harbor Works makes one product, a marine pump. It sells for 120 dollars per unit. Variable costs are 45 dollars direct materials, 25 dollars direct labor, and 10 dollars variable overhead per unit. Annual fixed costs are 480,000 dollars. The plant can make 12,000 pumps a year but currently sells 9,000. We will size up the business, then evaluate two proposals."},{"heading":"Worked analysis: cost structure and break-even","text":"Total variable cost per unit = 45 + 25 + 10 = 80 dollars, so contribution margin per unit = 120 - 80 = 40 dollars and the CM ratio = 40 / 120 = 0.333. Break-even in units = fixed costs / CM per unit = 480,000 / 40 = 12,000 units; break-even in dollars = 480,000 / 0.333 = about 1,440,000 dollars. At current sales of 9,000 units, contribution = 9,000 times 40 = 360,000 dollars, and operating income = 360,000 - 480,000 = -120,000 dollars, a loss. To reach a target profit of 60,000 dollars, required units = (480,000 + 60,000) / 40 = 540,000 / 40 = 13,500 units — above the 12,000 capacity, a warning that the current price and cost structure cannot hit that target without change."},{"heading":"Worked analysis: a special order and a make-or-buy","text":"Proposal A, special order: a distributor offers 95 dollars each for 2,000 pumps, using idle capacity (9,000 sold plus 2,000 still fits under 12,000) and not affecting regular sales. Relevant test: extra revenue 95 dollars minus extra variable cost 80 dollars = 15 dollars contribution per unit, times 2,000 = 30,000 dollars added profit. Fixed costs do not change, so accept — the loss shrinks by 30,000 dollars. Proposal B, make-or-buy a subassembly now costing 22 dollars to make (14 dollars avoidable variable plus 8 dollars allocated fixed that continues either way); a vendor offers it at 16 dollars. Relevant cost to make is the avoidable 14 dollars, which is below the 16 dollar purchase price, so keep making it — buying would add 2 dollars per unit. Notice both decisions turned on relevant costs: idle-capacity contribution in A, and avoidable versus purchase cost in B, with unchanged fixed costs ignored."},{"heading":"Your turn","text":"Stay with Harbor Works (CM per unit 40 dollars, fixed costs 480,000 dollars, price 120 dollars, variable 80 dollars). 1) How many units are needed to break even? 2) What is operating income at 11,000 units? 3) A special order offers 90 dollars per unit with idle capacity — what is the contribution per unit? 4) Would you accept a 1,000-unit order at 90 dollars, and what is the profit effect? 5) For the subassembly, if the vendor price dropped to 13 dollars versus the 14 dollar avoidable make cost, make or buy? Answers: 1) 480,000 / 40 = 12,000 units. 2) 11,000 times 40 - 480,000 = 440,000 - 480,000 = -40,000 dollars. 3) 90 - 80 = 10 dollars. 4) accept — 10 times 1,000 = 10,000 dollars more profit. 5) buy, since 13 dollars is below the 14 dollar avoidable make cost."},{"heading":"Common mistakes & exit ticket","text":"Mistake: including the 8 dollar allocated fixed cost in the make-or-buy comparison — it continues either way and is irrelevant. Mistake: rejecting the 95 dollar special order because it is below the 120 dollar price, even though idle-capacity contribution is positive. Exit: (a) What is Harbor Works'' break-even in units? (b) In the special order, which costs did we ignore and why? Answers: 12,000 units; the unchanged fixed costs, because they do not differ between accepting and rejecting the order."}]}'::jsonb, 'Real decisions chain the tools together: classify costs, find contribution margin and break-even, then isolate only the relevant costs for the choice at hand.', 16),
  (15, 'Comprehensive final quiz', 'quiz', '{"questions":[{"prompt":"Which is a defining feature of managerial accounting relative to financial accounting?","options":["It is mandated by GAAP for external users","It is flexible, internal, and often forward-looking","It always covers the whole company only","It is audited for investors"],"answer":1,"explanation":"Managerial accounting serves internal decisions without a mandated format and looks ahead."},{"prompt":"A cost that stays constant in total but changes per unit as volume changes is…","options":["variable","fixed","a sunk cost","an opportunity cost"],"answer":1,"explanation":"Fixed costs are constant in total; their per-unit amount falls as volume rises."},{"prompt":"Using high-low with 4,600 dollars at 1,500 hours and 3,400 dollars at 900 hours, the fixed portion is…","options":["1,000 dollars","1,600 dollars","2,000 dollars","3,000 dollars"],"answer":1,"explanation":"Variable rate is 2 dollars per hour; fixed = 4,600 - 2 times 1,500 = 1,600 dollars."},{"prompt":"A product sells for 50 dollars with 30 dollars variable cost and 60,000 dollars fixed costs. Break-even in units is…","options":["1,200","2,000","3,000","6,000"],"answer":2,"explanation":"CM per unit = 50 - 30 = 20; break-even = 60,000 / 20 = 3,000 units."},{"prompt":"For a target profit of 30,000 dollars with a 20 dollar CM and 60,000 dollars fixed costs, required units are…","options":["1,500","3,000","4,500","9,000"],"answer":2,"explanation":"(60,000 + 30,000) / 20 = 90,000 / 20 = 4,500 units."},{"prompt":"A predetermined overhead rate is estimated overhead divided by…","options":["actual overhead","estimated activity in the allocation base","total sales dollars","units sold"],"answer":1,"explanation":"The rate is set before the period as estimated overhead / estimated allocation base."},{"prompt":"A department completes 5,000 units and has 2,000 units 25 percent complete. Equivalent units equal…","options":["5,000","5,500","7,000","2,500"],"answer":1,"explanation":"5,000 + (2,000 times 0.25) = 5,000 + 500 = 5,500 equivalent units."},{"prompt":"An activity cost pool of 60,000 dollars over 3,000 inspections yields an activity rate of…","options":["2 dollars per inspection","20 dollars per inspection","50 dollars per inspection","200 dollars per inspection"],"answer":1,"explanation":"60,000 / 3,000 = 20 dollars per inspection."},{"prompt":"Standard usage is 2,000 pounds but 2,100 were used at a standard price of 3 dollars. The quantity variance is…","options":["300 dollars unfavorable","420 dollars unfavorable","300 dollars favorable","600 dollars unfavorable"],"answer":0,"explanation":"(2,100 - 2,000) times 3 = 100 times 3 = 300 dollars unfavorable."},{"prompt":"In a make-or-buy decision, an allocated fixed cost that continues regardless of the choice is…","options":["relevant and included","irrelevant and ignored","the deciding factor","an opportunity cost"],"answer":1,"explanation":"Only avoidable, future, differing costs are relevant; unavoidable fixed costs drop out."},{"prompt":"With idle capacity, a special order priced at 18 dollars with 15 dollars variable cost per unit adds contribution per unit of…","options":["3 dollars","15 dollars","18 dollars","33 dollars"],"answer":0,"explanation":"18 - 15 = 3 dollars of contribution per unit, since fixed costs do not change."},{"prompt":"A division with 150,000 dollars operating income, 750,000 dollars average operating assets, and a 10 percent required return has residual income of…","options":["15,000 dollars","75,000 dollars","150,000 dollars","0 dollars"],"answer":1,"explanation":"150,000 - (0.10 times 750,000) = 150,000 - 75,000 = 75,000 dollars."}]}'::jsonb, null, 12)
) as v(pos, title, kind, body, notes, mins)
where not exists (
  select 1 from public.lessons l
  where l.course_id = 'bbbb0003-0000-4000-8000-000000000015' and l.position = v.pos
);
